import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import * as fs from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';

const model = '.kogen/intents/quint-spec-replay-overhaul/model.qnt';
const required = [['init', ['public', 'public', 'preview', 'preview', 'public']], ['previewFirst', ['preview']]];
const cwd = process.cwd();
const read = (base, f) => fs.readFileSync(join(base, f), 'utf8');
const json = (base, f) => JSON.parse(read(base, f));
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const digest = file => sha(fs.readFileSync(file));
const write = (dir, f, data) => fs.writeFileSync(join(dir, f), JSON.stringify(data, null, 2) + '\n');
const env = { ...process.env, ASTRO_TELEMETRY_DISABLED: '1' };
delete env.SITE_MODE;

function command(program, args, { work = cwd, log, vars = env, timeout = 5000 } = {}) {
  const result = spawnSync(program, args, { cwd: work, env: vars, timeout, encoding: 'utf8' });
  if (log) fs.writeFileSync(log, (result.stdout || '') + (result.stderr || ''));
  if (result.error || result.status !== 0) throw new Error(`${program} ${args.join(' ')}: ${result.error || result.stderr || result.signal || result.status}`);
  return result.stdout;
}
const git = (...args) => command('git', ['--no-optional-locks', ...args]);

function getStates(raw, plan, id) {
  const trace = JSON.parse(raw);
  assert.equal(trace['#meta']?.format, 'ITF');
  assert.equal(trace['#meta']?.status, 'ok');
  assert.equal(trace['#meta']?.source, model);
  assert.deepEqual(trace.states.map(state => state.mode), ['clean', ...plan], `${id}: required state sequence`);
  trace.states.forEach((state, i) => {
    assert.equal(state['#meta'].index, i);
    assert.equal(state.cursor['#bigint'], String(i));
    assert.deepEqual(state.plan, plan);
    assert.equal(state.exports, i > 0);
    for (const flag of ['indexable', 'sitemap']) assert.equal(state[flag], state.mode === 'public');
  });
  return trace.states.slice(1);
}

function observe(work, state, label) {
  const dist = join(work, 'dist');
  const site = json(work, 'content/site.json');
  const origin = site.origin;
  const html = read(dist, 'index.html');
  assert.deepEqual([...html.matchAll(/<meta name="robots" content="([^"]+)"/g)].map(m => m[1]), [state.indexable ? 'index,follow' : 'noindex,nofollow'], `${label}: homepage robots`);
  assert.equal(read(dist, 'robots.txt'), state.indexable ? `User-agent: *\nAllow: /\n\nSitemap: ${origin}/sitemap.xml\n` : 'User-agent: *\nDisallow: /\n', `${label}: robots policy`);
  assert.equal(html.includes(`<link rel="canonical" href="${origin}/">`), state.indexable, `${label}: homepage canonical`);
  if (site.plausibleScriptUrl) assert.equal(html.includes('src="/analytics.js"'), state.indexable, `${label}: homepage analytics wiring`);
  for (const dir of ['public', 'dist']) assert.equal(fs.existsSync(join(work, dir, 'sitemap.xml')), state.sitemap, `${label}: ${dir} sitemap`);
  if (state.sitemap) assert.deepEqual([...read(dist, 'sitemap.xml').matchAll(/<loc>([^<]+)<\/loc>/g)].map(m => m[1]), [...new Set([...site.routes, '/about/', '/contact/', '/privacy/', '/sponsors/'])].map(route => origin + route), `${label}: sitemap URLs`);
  const authored = ['setup.md', ...['stack', 'app-guide', 'optional', 'runtime'].flatMap(name => [`${name}.md`, `${name}.json`])];
  const stable = [...authored, 'agents.md', 'llms.txt', 'agent-content/index.md'];
  for (const file of authored) assert.equal(read(dist, file), read(join(work, '.generated'), file), `${label}: ${file} disagrees with generator`);
  for (const stem of ['stack', 'app-guide', 'optional', 'runtime']) assert.equal(read(dist, `${stem}.json.md`), read(dist, `${stem}.md`), `${label}: ${stem} twin`);
  for (const route of ['about', 'contact', 'privacy', 'sponsors']) {
    assert.ok(read(dist, `${route}/index.html`).includes('<h1>'), `${label}: absent ${route} page heading`);
    assert.equal(read(dist, `${route}.md`), read(dist, `agent-content/${route}.md`), `${label}: ${route} twin`);
    stable.push(`${route}.md`);
  }
  assert.equal(read(dist, 'llms.txt').split('## Business information').length, 2, `${label}: business information appears once`);
  return Object.fromEntries(stable.map(file => {
    assert.ok(read(dist, file).trim(), `${label}: empty ${file}`);
    return [file, digest(join(dist, file))];
  }));
}

