  const source = { repository: 'optimumBA/elixir.menu', cutover: 'quint-mbt-cutover-20261125', head: git('rev-parse', 'HEAD').trim(), tree: git('rev-parse', 'HEAD^{tree}').trim(), status: git('status', '--porcelain=v1', '--untracked-files=all'), files: {} };
  const tracked = [...new Set(git('ls-files', '-z', '--cached', '--others', '--exclude-standard').split('\0').filter(Boolean))].sort();
  const inputs = tracked.filter(file => fs.existsSync(file)).map(file => [file, fs.readFileSync(file)]);
  source.files = Object.fromEntries(inputs.map(([file, bytes]) => [file, sha(bytes)]));
  const evidence = resolve(process.argv[2]);
  fs.mkdirSync(evidence);
  write(evidence, 'source.json', source);
  write(evidence, 'tools.json', tools);
  const paths = required.map(([id, plan]) => {
    const dir = join(evidence, id);
    fs.mkdirSync(dir);
    const traceFile = join(dir, 'trace.itf.json');
    const args = [quint, 'run', model, '--backend=typescript', `--init=${id}`, '--seed=1', '--max-samples=1', `--max-steps=${plan.length}`, '--invariant=consistent', `--out-itf=${traceFile}`];
    command(process.execPath, args, { log: join(dir, 'quint.log'), timeout: 10000 });
    const raw = fs.readFileSync(traceFile);
    return { id, states: getStates(raw, plan, id), traceSha256: sha(raw), quintCommand: [process.execPath, ...args] };
  });
  let first;
  const report = paths.map(({ id, states, traceSha256, quintCommand }) => {
    const work = fs.mkdtempSync(join(tmpdir(), 'elixir-menu-replay-'));
    const pathDir = join(evidence, id);
    try {
      for (const [file, bytes] of inputs) {
        fs.mkdirSync(dirname(join(work, file)), { recursive: true });
        fs.writeFileSync(join(work, file), bytes);
      }
      fs.symlinkSync(join(cwd, 'node_modules'), join(work, 'node_modules'), 'dir');
      for (const statePath of ['.generated', 'dist', 'public/sitemap.xml', 'public/robots.txt']) assert.ok(!fs.existsSync(join(work, statePath)), `${id}: expected clean ${statePath}`);
      const builds = states.map((state, i) => {
        const label = `${id}/${i + 1}`;
        const snapshot = join(evidence, label);
        fs.mkdirSync(snapshot);
        const siteMode = state.mode === 'preview' ? 'preview' : null;
        const vars = siteMode ? { ...env, SITE_MODE: siteMode } : env;
        const args = ['run', 'build'];
        command('npm', args, { work, vars, log: join(snapshot, 'build.log'), timeout: 10000 });
        const hashes = observe(work, state, label);
        if (!first) first = hashes;
        else assert.deepEqual(hashes, first, `${label}: editorial exports changed across rebuild or mode`);
        fs.cpSync(join(work, 'dist'), join(snapshot, 'dist'), { recursive: true });
        return { mode: state.mode, exit: 0, command: ['npm', ...args], siteMode, hashes };
      });
      return { id, traceSha256, quintCommand, builds };
    } finally {
      fs.rmSync(work, { recursive: true, force: true });
    }
  });
  write(evidence, 'report.json', { paths: report });
}
try {
  main();
} catch (error) {
